import React from 'react';
import { PanelMenu } from 'primereact/panelmenu';
import { Badge } from 'primereact/badge';


export default function Template() {
    const itemRenderer = (item, options) => (
        <a className="panelmenu-action fxb fvc gp2 pd4" onClick={options.onClick}>
            <span className={`${item.icon} fg-primary`} />
            <span className={`mgx2 ${item.items && 'font-semibold'}`}>{item.label}</span>
            {item.badge && <Badge className="mgl-auto" value={item.badge} />}
            {item.shortcut && <span className="mgl-auto bd pd3 font-size12 bg-layer2 rds2">{item.shortcut}</span>}
        </a>
    );

    const items = [
        {
            label: 'Mail',
            icon: 'pi pi-envelope',
            badge: 5,
            template: itemRenderer,
            items: [
                {
                    label: 'Compose',
                    icon: 'pi pi-file-edit',
                    shortcut: '⌘+N',
                    template: itemRenderer
                },
                {
                    label: 'Inbox',
                    icon: 'pi pi-inbox',
                    badge: 5,
                    template: itemRenderer
                },
                {
                    label: 'Sent',
                    icon: 'pi pi-send',
                    shortcut: '⌘+S',
                    template: itemRenderer
                },
                {
                    label: 'Trash',
                    icon: 'pi pi-trash',
                    shortcut: '⌘+T',
                    template: itemRenderer
                }
            ]
        },
        {
            label: 'Reports',
            icon: 'pi pi-chart-bar',
            shortcut: '⌘+R',
            template: itemRenderer,
            items: [
                {
                    label: 'Sales',
                    icon: 'pi pi-chart-line',
                    badge: 3,
                    template: itemRenderer
                },
                {
                    label: 'Products',
                    icon: 'pi pi-list',
                    badge: 6,
                    template: itemRenderer
                }
            ]
        },
        {
            label: 'Profile',
            icon: 'pi pi-user',
            shortcut: '⌘+W',
            template: itemRenderer,
            items: [
                {
                    label: 'Settings',
                    icon: 'pi pi-cog',
                    shortcut: '⌘+O',
                    template: itemRenderer
                },
                {
                    label: 'Privacy',
                    icon: 'pi pi-shield',
                    shortcut: '⌘+P',
                    template: itemRenderer
                }
            ]
        }
    ];

    return (
        <PanelMenu model={items} className="w250" />
    )

}